const { pool, withTransaction } = require('../config/db');
const AppError = require('../utils/AppError');

const PROFILE_COLS = `id, username, display_name AS "displayName",
           bio, avatar_url AS "avatarUrl",
           is_private AS "isPrivate",
           is_verified_creator AS "isVerifiedCreator",
           created_at AS "createdAt"`;

const SETTINGS_COLS = `show_online_status AS "showOnlineStatus",
             liked_posts_private AS "likedPostsPrivate",
             allow_messages_from AS "allowMessagesFrom",
             language, notif_prefs AS "notifPrefs"`;

const PUBLIC_POSTS_SQL = `SELECT COUNT(*)::int AS count FROM posts
      WHERE author_id = $1 AND deleted_at IS NULL AND is_draft = false AND is_anonymous = false`;

async function getMyProfile(userId) {
  const userRes = await pool.query(
    `SELECT ${PROFILE_COLS}, status, role FROM users WHERE id = $1 AND status = 'active'`, [userId]);
  if (userRes.rowCount === 0) throw new AppError(404, 'User not found', 'USER_NOT_FOUND');

  // FIX: the settings row must exist BEFORE it is selected (draft ran both in parallel).
  // FIX: use the table defaults instead of hard-coded values (draft set liked_posts_private=false).
  await pool.query('INSERT INTO user_settings (user_id) VALUES ($1) ON CONFLICT (user_id) DO NOTHING', [userId]);

  const [postsRes, followersRes, followingRes, settingsRes] = await Promise.all([
    pool.query(PUBLIC_POSTS_SQL, [userId]),
    pool.query('SELECT COUNT(*)::int AS count FROM follows WHERE following_id = $1', [userId]),
    pool.query('SELECT COUNT(*)::int AS count FROM follows WHERE follower_id = $1', [userId]),
    pool.query(`SELECT ${SETTINGS_COLS} FROM user_settings WHERE user_id = $1`, [userId])
  ]);

  return {
    ...userRes.rows[0],
    counts: {
      posts: postsRes.rows[0].count,
      followers: followersRes.rows[0].count,
      following: followingRes.rows[0].count
    },
    settings: settingsRes.rows[0] || {}
  };
}

async function getProfileByUsername(viewerId, username) {
  const userRes = await pool.query(
    `SELECT ${PROFILE_COLS} FROM users WHERE username = $1 AND status = 'active'`, [username]);
  if (userRes.rowCount === 0) throw new AppError(404, 'User not found', 'USER_NOT_FOUND');
  const user = userRes.rows[0];

  if (viewerId && viewerId !== user.id) {
    const blockRes = await pool.query(
      `SELECT 1 FROM blocks
        WHERE (blocker_id = $1 AND blocked_id = $2) OR (blocker_id = $2 AND blocked_id = $1) LIMIT 1`,
      [viewerId, user.id]);
    if (blockRes.rowCount > 0) throw new AppError(404, 'User not found', 'USER_NOT_FOUND');
  }

  const none = { rowCount: 0 };
  const [postsRes, followersRes, followingRes, isFollowingRes, hasRequestedRes, followsYouRes] = await Promise.all([
    pool.query(PUBLIC_POSTS_SQL, [user.id]),
    pool.query('SELECT COUNT(*)::int AS count FROM follows WHERE following_id = $1', [user.id]),
    pool.query('SELECT COUNT(*)::int AS count FROM follows WHERE follower_id = $1', [user.id]),
    viewerId ? pool.query('SELECT 1 FROM follows WHERE follower_id = $1 AND following_id = $2 LIMIT 1', [viewerId, user.id]) : none,
    viewerId ? pool.query(`SELECT 1 FROM follow_requests WHERE requester_id = $1 AND target_id = $2 AND status = 'pending' LIMIT 1`, [viewerId, user.id]) : none,
    viewerId ? pool.query('SELECT 1 FROM follows WHERE follower_id = $1 AND following_id = $2 LIMIT 1', [user.id, viewerId]) : none
  ]);

  const isSelf = viewerId === user.id;
  const isFollowing = isFollowingRes.rowCount > 0;

  return {
    ...user,
    counts: {
      posts: postsRes.rows[0].count,
      followers: followersRes.rows[0].count,
      following: followingRes.rows[0].count
    },
    relationship: {
      isSelf,
      isFollowing,
      hasRequested: hasRequestedRes.rowCount > 0,
      followsYou: followsYouRes.rowCount > 0,
      isBlocked: false
    },
    canViewPosts: !user.isPrivate || isSelf || isFollowing
  };
}

const PROFILE_FIELDS = { displayName: 'display_name', bio: 'bio', avatarUrl: 'avatar_url', isPrivate: 'is_private' };
const SETTINGS_FIELDS = {
  showOnlineStatus: 'show_online_status', likedPostsPrivate: 'liked_posts_private',
  allowMessagesFrom: 'allow_messages_from', language: 'language'
};

async function updateProfile(userId, fields) {
  const sets = [];
  const params = [];
  for (const [key, value] of Object.entries(fields)) {
    const column = PROFILE_FIELDS[key];
    if (!column || value === undefined) continue;
    params.push(value);
    sets.push(`${column} = $${params.length}`);
  }
  if (sets.length === 0) throw new AppError(400, 'No valid fields provided', 'INVALID_FIELDS');
  params.push(userId);

  return withTransaction(async (client) => {
    const res = await client.query(
      `UPDATE users SET ${sets.join(', ')} WHERE id = $${params.length} AND status = 'active'
       RETURNING ${PROFILE_COLS}, status, role`, params);
    if (res.rowCount === 0) throw new AppError(404, 'User not found', 'USER_NOT_FOUND');

    // FIX (added): going public must accept the pending follow requests, otherwise they are stuck forever.
    if (fields.isPrivate === false) {
      await client.query(
        `INSERT INTO follows (follower_id, following_id)
         SELECT requester_id, target_id FROM follow_requests WHERE target_id = $1 AND status = 'pending'
         ON CONFLICT DO NOTHING`, [userId]);
      await client.query(
        `UPDATE follow_requests SET status = 'accepted' WHERE target_id = $1 AND status = 'pending'`, [userId]);
    }
    return res.rows[0];
  });
}

async function getSettings(userId) {
  await pool.query('INSERT INTO user_settings (user_id) VALUES ($1) ON CONFLICT (user_id) DO NOTHING', [userId]);
  const res = await pool.query(`SELECT ${SETTINGS_COLS} FROM user_settings WHERE user_id = $1`, [userId]);
  return res.rows[0] || {};
}

// FIX: the draft's upsert built a broken parameter list. Rewritten: ensure the row exists, then UPDATE.
async function updateSettings(userId, fields) {
  const sets = [];
  const params = [];
  for (const [key, value] of Object.entries(fields)) {
    const column = SETTINGS_FIELDS[key];
    if (!column || value === undefined) continue;
    params.push(value);
    sets.push(`${column} = $${params.length}`);
  }
  if (sets.length === 0) throw new AppError(400, 'No valid fields provided', 'INVALID_FIELDS');
  params.push(userId);

  await pool.query('INSERT INTO user_settings (user_id) VALUES ($1) ON CONFLICT (user_id) DO NOTHING', [userId]);
  const res = await pool.query(
    `UPDATE user_settings SET ${sets.join(', ')} WHERE user_id = $${params.length} RETURNING ${SETTINGS_COLS}`, params);
  return res.rows[0];
}

function escapeLike(pattern) {
  return pattern.replace(/[\\%_]/g, '\\$&');
}

async function searchUsers(viewerId, q, limit) {
  const escaped = escapeLike(q);
  const params = [`%${escaped}%`, `${escaped}%`];
  // FIX: draft declared this with const and then used += (TypeError at runtime).
  let sql = `
    SELECT id, username, display_name AS "displayName", avatar_url AS "avatarUrl",
           is_verified_creator AS "isVerifiedCreator"
      FROM users
     WHERE status = 'active'
       AND (username ILIKE $1 ESCAPE '\\' OR display_name ILIKE $1 ESCAPE '\\')`;

  if (viewerId) {
    params.push(viewerId);
    sql += `
       AND NOT EXISTS (
         SELECT 1 FROM blocks b
          WHERE (b.blocker_id = $${params.length} AND b.blocked_id = users.id)
             OR (b.blocker_id = users.id AND b.blocked_id = $${params.length}))`;
  }

  params.push(limit);
  // FIX: rank real prefix matches ($2) first (draft ranked against the same pattern as the filter).
  sql += `
     ORDER BY CASE WHEN username ILIKE $2 ESCAPE '\\' THEN 0
                   WHEN display_name ILIKE $2 ESCAPE '\\' THEN 1 ELSE 2 END,
              username
     LIMIT $${params.length}`;

  const res = await pool.query(sql, params);
  return res.rows;
}

module.exports = { getMyProfile, getProfileByUsername, updateProfile, getSettings, updateSettings, searchUsers };
